['Light','Dark'].forEach(function(a){var p=H.page('Proto macOS '+a),ss=p.layers.filter(function(s){return s.name.indexOf('Screen/macos/')===0;});console.log(JSON.stringify({appearance:a,count:ss.length}));ss.forEach(function(s){var id=s.name.split('/').pop();if(['signin','conversation--menu','customize--profile','settings-appearance','projects','new-conversation','artifacts--detail','settings--sign-out','settings-billing--plan'].indexOf(id)<0)return;function walk(l){if(/email-field|traffic-lights|menu|popover|arrow|checkbox|control:|form:|^alert$|sheet|name-input|sf:.*export/.test(l.name))console.log(JSON.stringify({appearance:a,screen:id,id:l.id,name:l.name,text:l.text,x:l.frame.x,y:l.frame.y,w:l.frame.width,h:l.frame.height,parent:l.parent.name}));if(l.type==='Text'&&l.name.indexOf('sf:')===0&&id==='conversation--menu')console.log(JSON.stringify({appearance:a,screen:id,glyph:l.name,cp:l.text.codePointAt(0),parent:l.parent.name}));(l.layers||[]).forEach(walk);}walk(s);});});